create extension if not exists "pgcrypto";
create table public.profiles (id uuid primary key references auth.users on delete cascade, username text unique not null, full_name text, avatar_url text, bio text, country text, city text, privacy text default 'public', created_at timestamptz default now());
create table public.watch_models (id uuid primary key default gen_random_uuid(), brand text not null, model text not null, reference text, movement text, caliber text, diameter_mm numeric, thickness_mm numeric, lug_width_mm numeric, material text, crystal text, water_resistance_m integer, description text, created_at timestamptz default now());
create table public.watches (id uuid primary key default gen_random_uuid(), owner_id uuid references public.profiles on delete cascade not null, model_id uuid references public.watch_models, brand text not null, model text not null, reference text, serial_encrypted text, production_year integer, purchase_date date, purchase_price numeric, current_value numeric, currency text default 'EUR', condition text, status text default 'collection', visibility text default 'public', notes text, created_at timestamptz default now());
create table public.watch_photos (id uuid primary key default gen_random_uuid(), watch_id uuid references public.watches on delete cascade not null, owner_id uuid references public.profiles on delete cascade not null, storage_path text not null, caption text, sort_order integer default 0, created_at timestamptz default now());
create table public.maintenance (id uuid primary key default gen_random_uuid(), watch_id uuid references public.watches on delete cascade not null, owner_id uuid references public.profiles on delete cascade not null, type text not null, performed_at date, due_at date, provider text, cost numeric default 0, notes text, status text default 'planned', created_at timestamptz default now());
create table public.posts (id uuid primary key default gen_random_uuid(), author_id uuid references public.profiles on delete cascade not null, watch_id uuid references public.watches on delete set null, model_id uuid references public.watch_models on delete set null, body text not null, image_url text, created_at timestamptz default now());
create table public.comments (id uuid primary key default gen_random_uuid(), post_id uuid references public.posts on delete cascade not null, author_id uuid references public.profiles on delete cascade not null, body text not null, created_at timestamptz default now());
create table public.likes (post_id uuid references public.posts on delete cascade, user_id uuid references public.profiles on delete cascade, created_at timestamptz default now(), primary key(post_id,user_id));
create table public.follows (follower_id uuid references public.profiles on delete cascade, following_id uuid references public.profiles on delete cascade, created_at timestamptz default now(), primary key(follower_id,following_id));
create table public.listings (id uuid primary key default gen_random_uuid(), seller_id uuid references public.profiles on delete cascade not null, watch_id uuid references public.watches on delete set null, title text not null, description text, price numeric not null, currency text default 'EUR', condition text, location text, status text default 'active', created_at timestamptz default now());
alter table public.profiles enable row level security; alter table public.watches enable row level security; alter table public.watch_photos enable row level security; alter table public.maintenance enable row level security; alter table public.posts enable row level security; alter table public.comments enable row level security; alter table public.likes enable row level security; alter table public.follows enable row level security; alter table public.listings enable row level security;
create policy "profiles public read" on public.profiles for select using (true); create policy "profiles own update" on public.profiles for update using (auth.uid()=id);
create policy "watches visible read" on public.watches for select using (visibility='public' or owner_id=auth.uid()); create policy "watches own all" on public.watches for all using (owner_id=auth.uid()) with check (owner_id=auth.uid());
create policy "maintenance own all" on public.maintenance for all using (owner_id=auth.uid()) with check (owner_id=auth.uid());
create policy "posts public read" on public.posts for select using (true); create policy "posts own insert" on public.posts for insert with check (author_id=auth.uid()); create policy "posts own modify" on public.posts for all using (author_id=auth.uid());
create policy "comments public read" on public.comments for select using (true); create policy "comments own" on public.comments for all using (author_id=auth.uid()) with check (author_id=auth.uid());
create policy "listings public read" on public.listings for select using (true); create policy "listings own" on public.listings for all using (seller_id=auth.uid()) with check (seller_id=auth.uid());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,username,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'username',split_part(new.email,'@',1)),new.raw_user_meta_data->>'full_name'); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
